# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.seating import seating_rows


def make_student(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make_student("Halloway", "Juno"),
            make_student("Zane", "Omar"),
            make_student("Dunmere", "Piet"),
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Omar",
            ],
        )

    def test_first_name_breaks_ties(self):
        people = [
            make_student("Reed", "Zoe"),
            make_student("Reed", "Abel"),
        ]
        self.assertEqual(
            seating_rows(people, 5),
            ["Row 1: Reed, Abel | Reed, Zoe"],
        )

    def test_bad_seat_counts(self):
        people = [make_student("Reed", "Zoe")]
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
